-- PostgreSQL target schema. Mirrors the live D1 operational model before adding growth tables.
-- Business-local wall times (visit/booking/transaction) remain ISO TEXT for lossless D1 migration.
CREATE TABLE business (id text PRIMARY KEY, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Jakarta', currency text NOT NULL DEFAULT 'IDR', status text NOT NULL DEFAULT 'active', created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE branch (id text PRIMARY KEY, business_id text NOT NULL REFERENCES business(id), name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Jakarta', status text NOT NULL DEFAULT 'active', created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE app_user (id text PRIMARY KEY, business_id text NOT NULL REFERENCES business(id), display_name text NOT NULL, username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('owner','operator','capster')), status text NOT NULL DEFAULT 'active', failed_logins integer NOT NULL DEFAULT 0, locked_until text, created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE session (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id), expires_at text NOT NULL, created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_session_user ON session(user_id);
CREATE TABLE capster (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), user_id text REFERENCES app_user(id), display_name text NOT NULL, status text NOT NULL DEFAULT 'active', created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), external_customer_id text, name text, whatsapp text, normalized_whatsapp text, first_seen_at text, last_visit_at text, status text NOT NULL DEFAULT 'active', created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, request_hash text);
CREATE UNIQUE INDEX idx_customer_whatsapp ON customer(branch_id, normalized_whatsapp) WHERE normalized_whatsapp IS NOT NULL;
CREATE TABLE customer_consent (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customer(id), channel text NOT NULL, purpose text NOT NULL, status text NOT NULL CHECK(status IN ('yes','no','unknown')), captured_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, captured_by text REFERENCES app_user(id), source text NOT NULL, notes text);
CREATE INDEX idx_consent_latest ON customer_consent(customer_id, channel, purpose, captured_at DESC);
CREATE TABLE service (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), name text NOT NULL, category text, active integer NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at text);
CREATE TABLE price_rule (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), service_id text NOT NULL REFERENCES service(id), price integer NOT NULL CHECK(price >= 0), effective_from text NOT NULL, effective_to text, source text NOT NULL, created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_price_rule_service_from ON price_rule(service_id, effective_from DESC);
CREATE TABLE booking (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), customer_id text REFERENCES customer(id), booked_by text REFERENCES app_user(id), scheduled_start text NOT NULL, scheduled_end text, party_size integer NOT NULL DEFAULT 1 CHECK(party_size > 0), preferred_capster_id text REFERENCES capster(id), status text NOT NULL CHECK(status IN ('confirmed','arrived','in_service','completed','cancelled','no_show')), notes text, projected_value integer, created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, request_hash text);
CREATE INDEX idx_booking_branch_schedule ON booking(branch_id, scheduled_start);
CREATE TABLE booking_person (id text PRIMARY KEY, booking_id text NOT NULL REFERENCES booking(id), customer_id text REFERENCES customer(id), service_id text REFERENCES service(id), capster_id text REFERENCES capster(id), projected_unit_value integer CHECK(projected_unit_value >= 0), created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_booking_person_booking ON booking_person(booking_id);
CREATE TABLE visit (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), customer_id text REFERENCES customer(id), capster_id text REFERENCES capster(id), booking_id text REFERENCES booking(id), occurred_at text NOT NULL, status text NOT NULL CHECK(status IN ('expected','arrived','in_service','completed','cancelled','no_show')), service_summary text, source text NOT NULL, external_visit_id text, created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, service_id text REFERENCES service(id), request_hash text, booking_person_id text REFERENCES booking_person(id));
CREATE UNIQUE INDEX idx_visit_booking_person ON visit(booking_person_id) WHERE booking_person_id IS NOT NULL;
CREATE INDEX idx_visit_customer ON visit(customer_id, occurred_at);
CREATE INDEX idx_visit_branch_time ON visit(branch_id, occurred_at);
CREATE TABLE sync_run (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), source_system text NOT NULL, source_type text NOT NULL, started_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at text, status text NOT NULL, rows_seen integer NOT NULL DEFAULT 0, rows_imported integer NOT NULL DEFAULT 0, rows_skipped integer NOT NULL DEFAULT 0, rows_rejected integer NOT NULL DEFAULT 0, error_summary text, created_by text REFERENCES app_user(id));
CREATE TABLE transaction_snapshot (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), visit_id text REFERENCES visit(id), sync_run_id text NOT NULL REFERENCES sync_run(id), external_transaction_id text, transaction_time text NOT NULL, gross_amount integer CHECK(gross_amount IS NULL OR gross_amount >= 0), payment_method text, service_text text, capster_text text, source_system text NOT NULL, source_file_id text, source_row_number integer, imported_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, raw_fingerprint text NOT NULL, reconciliation_status text NOT NULL DEFAULT 'unresolved', customer_id text REFERENCES customer(id), customer_name text, customer_whatsapp text, reference_text text, UNIQUE(branch_id, source_system, raw_fingerprint));
CREATE UNIQUE INDEX idx_transaction_external ON transaction_snapshot(branch_id, source_system, external_transaction_id) WHERE external_transaction_id IS NOT NULL;
CREATE INDEX idx_transaction_customer ON transaction_snapshot(customer_id, transaction_time);
CREATE INDEX idx_transaction_time ON transaction_snapshot(branch_id, transaction_time);
CREATE TABLE reminder (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branch(id), customer_id text NOT NULL REFERENCES customer(id), visit_id text REFERENCES visit(id), due_at text NOT NULL, eligibility_status text NOT NULL, consent_status text NOT NULL, channel text NOT NULL, message_draft text, sent_at text, outcome text, created_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_reminder_customer_due ON reminder(branch_id, customer_id, due_at, channel);
CREATE TABLE reminder_event (id text PRIMARY KEY, reminder_id text NOT NULL REFERENCES reminder(id), event_type text NOT NULL, occurred_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, actor_user_id text REFERENCES app_user(id), metadata text);
CREATE TABLE audit_event (id text PRIMARY KEY, branch_id text REFERENCES branch(id), actor_user_id text REFERENCES app_user(id), action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, occurred_at text NOT NULL DEFAULT CURRENT_TIMESTAMP, before_snapshot text, after_snapshot text, metadata text);
CREATE INDEX idx_audit_time ON audit_event(occurred_at DESC);
